  const sep = /(?:^|[^A-Z0-9])LV[\s\-_./:]*(\d{1,6})[\s\-_./]+(?:([A-Z]{1,3})[\s\-_./]+)?(20\d{2})[\s\-_./]?(0[1-9]|1[0-2])(?![0-9])/g;
  let m;
  while ((m = sep.exec(up))) {
    if (validPeriod(m[3], m[4])) return build(m[1], m[2], m[3] + m[4], m[0], true, pricingRows);
