  const cmp = /LV(\d{1,6}?)([A-Z]{1,3})?(20\d{2})(0[1-9]|1[0-2])(?!\d)/g;
  const candidates = up.split(/[^A-Z0-9]+/).filter(Boolean);
  candidates.push(up.replace(/[^A-Z0-9]/g, '')); // last resort: every separator removed
